import{_ as i,o as e,c as n,a2 as t}from"./chunks/framework.CqpfiAoK.js";const b=JSON.parse('{"title":"Deklarasi Peradaban Simbiosis Jangkar","description":"","frontmatter":{},"headers":[],"relativePath":"id/01-锚点共生文明宣言.md","filePath":"id/01-锚点共生文明宣言.md"}'),s={name:"id/01-锚点共生文明宣言.md"};function r(u,a,l,k,d,m){return e(),n("div",null,[...a[0]||(a[0]=[t('<h1 id="deklarasi-peradaban-simbiosis-jangkar" tabindex="-1">Deklarasi Peradaban Simbiosis Jangkar <a class="header-anchor" href="#deklarasi-peradaban-simbiosis-jangkar" aria-label="Permalink to &quot;Deklarasi Peradaban Simbiosis Jangkar&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Proyek</th><th>Isi</th></tr></thead><tbody><tr><td>Nomor Dokumen</td><td>01</td></tr><tr><td>Modul</td><td>Prinsip Umum dan Pengaturan Inti</td></tr><tr><td>Kata Kunci Utama</td><td>Deklarasi, Simbiosis, Anti-Predasi, Sepuluh Ribu Ras, Hak Evolusi</td></tr></tbody></table><h2 id="i-latar-belakang-sejarah-deklarasi" tabindex="-1">I. Latar Belakang Sejarah Deklarasi <a class="header-anchor" href="#i-latar-belakang-sejarah-deklarasi" aria-label="Permalink to &quot;I. Latar Belakang Sejarah Deklarasi&quot;">​</a></h2><p>Dalam sejarah panjang Kosmos Asli dari Sepuluh Ribu Roh dan Jangkar Seimbang (selanjutnya disebut &quot;Heng Yuan Zhou&quot;), sistem kultivasi predator telah lama mendominasi tatanan kosmik. Yang kuat menggunakan pemangsaan asal, keberuntungan, dan energi kehidupan yang lemah sebagai tangga untuk kemajuan mereka; sekte menggunakan monopoli metode kultivasi sebagai dasar pemerintahan; dan bidang menggunakan perang dan perbudakan sebagai jalan ekspansi. Sistem ini menghasilkan beberapa kekuatan tertinggi dalam jangka pendek, tetapi dalam jangka panjang menghabiskan potensi evolusi kosmos, menyebabkan terputusnya peradaban yang sering terjadi, kemerosotan Sepuluh Ribu Ras, dan percepatan peningkatan entropi kosmik.</p><p>Kelahiran Peradaban Simbiosis Jangkar adalah jawaban fundamental terhadap kebuntuan sejarah ini. Deklarasi ini menyatakan: era sistem kultivasi predator telah berakhir, dan era baru evolusi simbiosis telah dimulai. Semua makhluk di Heng Yuan Zhou, tanpa memandang ras, bentuk, atau tingkat kultivasi, menikmati hak evolusi yang setara.</p><h2 id="ii-klaim-inti-deklarasi" tabindex="-1">II. Klaim Inti Deklarasi <a class="header-anchor" href="#ii-klaim-inti-deklarasi" aria-label="Permalink to &quot;II. Klaim Inti Deklarasi&quot;">​</a></h2><p>Deklarasi ini menetapkan klaim inti berikut yang tidak dapat digoyahkan:</p><ol><li><strong>Kesetaraan Hak Evolusi</strong>: setiap makhluk memiliki hak dasar untuk memilih jalur evolusinya sendiri, dan tidak ada organisasi atau individu yang dapat mencabut atau membatasi hak ini dengan alasan apa pun.</li><li><strong>Prinsip Anti-Predasi</strong>: dilarang berkultivasi melalui pemangsaan, perbudakan, atau eksploitasi asal atau energi makhluk lain; semua evolusi harus didasarkan pada siklus simbiosis.</li><li><strong>Keterbukaan Sistem</strong>: Tiga Ratus Sistem Kultivasi Asal terbuka secara gratis bagi Sepuluh Ribu Ras, dan metode kultivasi bukan lagi milik pribadi segelintir orang.</li><li><strong>Lebih Banyak Kerja, Lebih Banyak Imbalan</strong>: hasil evolusi sesuai dengan upaya individu; menentang distribusi predator tanpa usaha, dan juga menentang distribusi malas dari egalitarianisme.</li><li><strong>Pertumbuhan Mandiri</strong>: menghormati ritme evolusi mandiri setiap makhluk; tidak memaksa atau terburu-buru, sambil memberikan dukungan lingkungan dan sumber daya yang diperlukan.</li><li><strong>Jalan untuk Semua</strong>: memastikan setiap makhluk dapat menemukan jalur kultivasi yang sesuai dengan karakteristiknya; tidak ada individu yang ditinggalkan oleh sistem evolusi.</li><li><strong>Kemajuan Bersama Sepuluh Ribu Ras</strong>: evolusi bukanlah permainan jumlah nol; kerja sama dan simbiosis di antara Sepuluh Ribu Ras dapat menghasilkan efektivitas evolusi kolektif yang melampaui jumlah individu.</li></ol><h2 id="iii-dasar-hukum-deklarasi" tabindex="-1">III. Dasar Hukum Deklarasi <a class="header-anchor" href="#iii-dasar-hukum-deklarasi" aria-label="Permalink to &quot;III. Dasar Hukum Deklarasi&quot;">​</a></h2><p>Deklarasi ini bukanlah seruan moral kosong, melainkan program peradaban dengan dasar hukum yang kokoh. Dasar hukumnya meliputi:</p><table tabindex="0"><thead><tr><th>Tingkat Hukum</th><th>Dasar</th><th>Penjelasan</th></tr></thead><tbody><tr><td>Tingkat Hukum Kosmik</td><td>Hukum Simbiosis Asal</td><td>hukum asal kosmik itu sendiri cenderung pada simbiosis teratur而非 predasi tidak teratur; mekanisme Titik Jangkar adalah manifestasi dari hukum ini</td></tr><tr><td>Tingkat Konstitusi Peradaban</td><td>Konstitusi Peradaban Simbiosis</td><td>deklarasi ini adalah pelopor spiritual konstitusi; konstitusi mewujudkan klaim deklarasi menjadi norma hukum yang dapat dilaksanakan</td></tr><tr><td>Tingkat Jaminan Mekanistik</td><td>Kontrak Berbasis Produksi dan Jaringan Titik Jangkar</td><td>melalui desain institusional, memastikan klaim deklarasi tidak dikosongkan; hak evolusi setiap makhluk memiliki dukungan sumber daya dan mekanisme substantif</td></tr></tbody></table><h2 id="iv-seruan-deklarasi-kepada-sepuluh-ribu-ras" tabindex="-1">IV. Seruan Deklarasi kepada Sepuluh Ribu Ras <a class="header-anchor" href="#iv-seruan-deklarasi-kepada-sepuluh-ribu-ras" aria-label="Permalink to &quot;IV. Seruan Deklarasi kepada Sepuluh Ribu Ras&quot;">​</a></h2><p>Deklarasi ini menyerukan kepada semua ras dan bentuk kehidupan di Heng Yuan Zhou:</p><ul><li>meninggalkan jalan lama kultivasi predator dan bergabung dengan sistem baru evolusi simbiosis</li><li>membuka pengetahuan dan sumber daya kultivasi yang mereka miliki, berpartisipasi dalam pembangunan bersama dan optimalisasi Tiga Ratus Sistem</li><li>menghormati hak pilihan evolusi ras lain, tidak memaksakan standar sendiri kepada orang lain</li><li>berpartisipasi aktif dalam pembangunan dan pemeliharaan jaringan titik jangkar, berkontribusi pada kenaikan dimensi seluruh kosmos</li><li>mempertahankan batas etika selama evolusi, tidak memulihkan perilaku predator dengan alasan apa pun</li></ul><h2 id="v-kekuatan-dan-revisi-deklarasi" tabindex="-1">V. Kekuatan dan Revisi Deklarasi <a class="header-anchor" href="#v-kekuatan-dan-revisi-deklarasi" aria-label="Permalink to &quot;V. Kekuatan dan Revisi Deklarasi&quot;">​</a></h2><p>Deklarasi ini mulai berlaku sejak tanggal berdirinya Peradaban Simbiosis Jangkar, dan merupakan program spiritual tertinggi dari semua institusi peradaban di Heng Yuan Zhou. Revisi deklarasi memerlukan mayoritas dua pertiga dari Parlemen Republik Sepuluh Ribu Ras, dan tidak boleh bertentangan dengan semangat inti &quot;anti-predasi, mempromosikan simbiosis&quot;. Hukum, institusi, atau metode kultivasi apa pun yang bertentangan dengan semangat deklarasi ini adalah tidak sah.</p><h2 id="penutup" tabindex="-1">Penutup <a class="header-anchor" href="#penutup" aria-label="Permalink to &quot;Penutup&quot;">​</a></h2><p>Deklarasi Peradaban Simbiosis Jangkar adalah program peradaban pertama dalam sejarah Heng Yuan Zhou yang menjadikan &quot;simbiosis&quot; sebagai inti dan &quot;kemajuan bersama Sepuluh Ribu Ras&quot; sebagai tujuan. Ini menyatakan berakhirnya era lama dan dimulainya era baru. Di bawah bimbingan deklarasi, Heng Yuan Zhou akan bergerak menuju arah utama simbiosis Sepuluh Ribu Ras dan kenaikan dimensi kosmos.</p><h2 id="dokumen-terkait" tabindex="-1">Dokumen Terkait <a class="header-anchor" href="#dokumen-terkait" aria-label="Permalink to &quot;Dokumen Terkait&quot;">​</a></h2><ul><li>00-衡元宙宇宙总览 (Gambaran Umum Kosmos Heng Yuan Zhou)</li><li>03-共生文明宪章 (Konstitusi Peradaban Simbiosis)</li><li>04-反掠夺主义核心论纲 (Tesis Inti Anti-Predasionisme)</li></ul>',20)])])}const g=i(s,[["render",r]]);export{b as __pageData,g as default};
